-- Disposable fixtures; every test rolls back.
begin;
insert into auth.users(id) values('12121212-1212-4212-8212-121212121212'),('23232323-2323-4232-8232-232323232323');
create function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception '%',label; end if;end$$;
create function pg_temp.denied(stmt text) returns boolean language plpgsql as $$begin execute stmt; return false; exception when others then return true;end$$;
-- Service functions and quotas are not accessible to browsers.
set local role anon;
select set_config('request.jwt.claim.role','anon',true);
select pg_temp.assert_true(pg_temp.denied($q$select public.publish_meme_caption(gen_random_uuid(),'','')$q$),'anon publication');
select pg_temp.assert_true(pg_temp.denied('select public.reserve_meme_attempt()'),'anon provider quota');
reset role;
select set_config('request.jwt.claim.role','service_role',true);
do $$declare i int;begin for i in 1..10 loop perform public.reserve_meme_attempt();end loop;end$$;
select pg_temp.assert_true(pg_temp.denied('select public.reserve_meme_attempt()'),'11th minute attempt');
select pg_temp.assert_true((select attempts=10 from public.meme_provider_usage),'failed requests remain counted');
update public.meme_provider_usage set recent_attempts='{}',attempts=400;
select pg_temp.assert_true(pg_temp.denied('select public.reserve_meme_attempt()'),'401st daily attempt');
update public.meme_provider_usage set usage_date=(now() at time zone 'America/Los_Angeles')::date-1,recent_attempts='{}';
select public.reserve_meme_attempt();
select pg_temp.assert_true((select attempts=1 and usage_date=(now() at time zone 'America/Los_Angeles')::date from public.meme_provider_usage),'Pacific reset');
select set_config('meme.token',public.reserve_ai_generation('12121212-1212-4212-8212-121212121212')::text,true);
-- Model a live token reserved just before the user-day changed.
update public.ai_generation_usage set usage_date=usage_date-1 where user_id='12121212-1212-4212-8212-121212121212';
select set_config('meme.generation',public.finish_meme_caption('12121212-1212-4212-8212-121212121212',current_setting('meme.token')::uuid,'When the deadline moves','system','en','gemini-3.1-flash-lite','Great. More time to panic.','{"id":"405658","name":"Grumpy Cat","imageUrl":"https://imgflip.com/s/meme/Grumpy-Cat.jpg","sourceUrl":"https://imgflip.com/memetemplate/Grumpy-Cat","description":"Grumpy cat","width":500,"height":617}'::jsonb)::text,true);
select pg_temp.assert_true((select succeeded=1 and active_token is null from public.ai_generation_usage where user_id='12121212-1212-4212-8212-121212121212'),'reserved row finalized');
select pg_temp.assert_true(pg_temp.denied($q$select public.finish_meme_caption('12121212-1212-4212-8212-121212121212',gen_random_uuid(),'scene','system','en','gemini-3.1-flash-lite','caption','{}')$q$),'invalid token');
select public.reserve_ai_generation('23232323-2323-4232-8232-232323232323');
update public.ai_generation_usage set active_until=now()-interval '1 second' where user_id='23232323-2323-4232-8232-232323232323';
select pg_temp.assert_true(pg_temp.denied($q$select public.finish_meme_caption('23232323-2323-4232-8232-232323232323',(select active_token from public.ai_generation_usage where user_id='23232323-2323-4232-8232-232323232323'),'scene','system','en','gemini-3.1-flash-lite','caption',(select meme_template from public.ai_generations where id=current_setting('meme.generation')::uuid))$q$),'expired token');
update public.ai_generation_usage set succeeded=10;
select pg_temp.assert_true(pg_temp.denied($q$select public.reserve_ai_generation('23232323-2323-4232-8232-232323232323')$q$),'user success cap');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','23232323-2323-4232-8232-232323232323',true);
select pg_temp.assert_true(pg_temp.denied($q$select public.publish_meme_caption(current_setting('meme.generation')::uuid,'','')$q$),'cross-owner publish');
select pg_temp.assert_true(not exists(select 1 from public.ai_generations where id=current_setting('meme.generation')::uuid),'private prompt');
select pg_temp.assert_true(pg_temp.denied('select public.reserve_meme_attempt()'),'browser provider quota');
select set_config('request.jwt.claim.sub','12121212-1212-4212-8212-121212121212',true);
select set_config('meme.post',public.publish_meme_caption(current_setting('meme.generation')::uuid,'','')::text,true);
select pg_temp.assert_true(pg_temp.denied($q$select public.publish_meme_caption(current_setting('meme.generation')::uuid,'','')$q$),'duplicate publication');
select pg_temp.assert_true((select count(*)=1 from public.meme_feed_page('latest','all',0,true)),'owner feed');
select pg_temp.assert_true((select body='Great. More time to panic.' and scene='When the deadline moves' and template->>'id'='405658' and "canReuse" from public.meme_feed_page('latest','all',0,true)),'trusted public snapshot');
select pg_temp.assert_true(pg_temp.denied($q$update public.rants set body='forged' where id=current_setting('meme.post')::uuid$q$),'caption update');
select pg_temp.assert_true(pg_temp.denied($q$update public.rants set meme_template='{}' where id=current_setting('meme.post')::uuid$q$),'template update');
select pg_temp.assert_true(pg_temp.denied($q$insert into public.rants(user_id,title,location,body,generation_id) values(auth.uid(),'Fake','','forged',current_setting('meme.generation')::uuid)$q$),'direct forged insert');
select public.toggle_rant_vote(current_setting('meme.post')::uuid,1::smallint);
select pg_temp.assert_true((select totals->>'score'='1' and "myVote"=1 from public.meme_feed_page('popular','all',0,true)),'vote aggregate');
select public.toggle_rant_vote(current_setting('meme.post')::uuid,-1::smallint);
select pg_temp.assert_true((select totals->>'score'='-1' from public.meme_feed_page('popular','all',0,true)),'vote switch');
select public.toggle_rant_vote(current_setting('meme.post')::uuid,-1::smallint);
reset role;
select set_config('request.jwt.claim.role','service_role',true);
-- Publication window uses NY and excludes future works.
update public.rants set created_at=date_trunc('week',now() at time zone 'America/New_York') at time zone 'America/New_York' where id=current_setting('meme.post')::uuid;
select pg_temp.assert_true(exists(select 1 from public.meme_feed_page('latest','week',0,false)),'inclusive week');
update public.rants set created_at=created_at-interval '1 microsecond' where id=current_setting('meme.post')::uuid;
select pg_temp.assert_true(not exists(select 1 from public.meme_feed_page('latest','week',0,false)),'before week');
update public.rants set created_at=now()+interval '1 day' where id=current_setting('meme.post')::uuid;
select pg_temp.assert_true(not exists(select 1 from public.meme_feed_page('latest','all',0,false)),'future exclusion');
update public.rants set created_at=now() where id=current_setting('meme.post')::uuid;
set local role anon;
select set_config('request.jwt.claim.role','anon',true);
select set_config('request.jwt.claim.sub','',true);
select pg_temp.assert_true((select count(*)=1 from public.meme_feed_page('latest','all',0,false)),'public feed');
select pg_temp.assert_true(not exists(select 1 from public.meme_feed_page('latest','all',0,true)),'guest mine');
rollback;
